}

import { useEffect, useRef } from 'react'
import { useGithubAuth } from './auth/use_github_auth'
import { useAppBootstrap } from './app/use_app_bootstrap'
import { DialogDisplay } from './components/dialog_display'
import { MainWindow } from './components/shell/main_window'
import { StartupSplash } from './components/shell/startup_splash'
import { RemoteControlButton } from './components/shell/remote_control_button'
import { AppThemeProvider } from './theme/theme_provider'
import { readStartupSplashPreference } from './services/config/config_service'
import { dialogService } from './services/dialog_service'

export function App() {
    const auth = useGithubAuth()
    const bootstrap = useAppBootstrap(auth.accessToken)
    const showStartupSplash = readStartupSplashPreference()
    const reportedBootstrapErrorRef = useRef<string | null>(null)

    useEffect(() => {
        if (!bootstrap.error) {
            reportedBootstrapErrorRef.current = null

            return
        }

        if (bootstrap.error === reportedBootstrapErrorRef.current) return

        dialogService.error(`Could not restore last project: ${bootstrap.error}`)
        reportedBootstrapErrorRef.current = bootstrap.error
    }, [bootstrap.error])

    return (
        <AppThemeProvider>
            <DialogDisplay />
            {bootstrap.phase === 'starting' ? (
                showStartupSplash ? <StartupSplash /> : null
            ) : (
                <MainWindow
                    auth={auth}
                    toolbarAction={(
                        <RemoteControlButton />
                    )}
                />
            )}
        </AppThemeProvider>
    )
}

import { useSyncExternalStore } from 'react'
import { dataService, type DataService, type DataServiceState } from '../../services/data/data_service'

const snapshots = new WeakMap<DataService, DataServiceState>()

function isSameDataServiceState(first: DataServiceState, second: DataServiceState) {
    return first.project === second.project
        && first.runningAgents === second.runningAgents
        && first.snapshot === second.snapshot
}

function getProjectStateSnapshot(service: DataService): DataServiceState {
    const nextSnapshot = service.getState()
    const currentSnapshot = snapshots.get(service)
    if (currentSnapshot && isSameDataServiceState(currentSnapshot, nextSnapshot)) return currentSnapshot

    snapshots.set(service, nextSnapshot)

    return nextSnapshot
}

export function useProjectState(service: DataService = dataService): DataServiceState {
    return useSyncExternalStore(
        (onStoreChange) => {
            service.addEventListener('changed', onStoreChange)

            return () => service.removeEventListener('changed', onStoreChange)
        },
        () => getProjectStateSnapshot(service),
        () => getProjectStateSnapshot(service),
    )
}

