        this.dependencies.replaceProject(project)

        try {
            const projectConfig = await this.loadProjectConfig(project)
            if (projectConfig === null) await this.saveMissingProjectConfig(project)

            const config = resolveProjectConfigPaths(configService.getProjectConfig())
            if (config.pushMode === 'manual') {
                await storage.restorePendingCommits?.(project)
                await this.loadPendingPush(project)
            }

            await this.loadActions(project, config.actionsFolder)
            const projectFiles = await storage.loadProjectRoot(project, config.workingFolder)
            const repositoryFiles: string[] = []
            this.dependencies.replaceProjectFiles(projectFiles.files, config.workingFolder, repositoryFiles)
            await this.dependencies.ensureCardInternalIds()
            this.tryStartProjectWatch()
            const currentSnapshot = this.dependencies.snapshot()
            if (!currentSnapshot) throw new Error('Project snapshot was not created')
            initializeMissingProjectStates(projectConfig ?? null, currentSnapshot)
            this.dependencies.dispatchChanged()
            reportActionLoadIssues()

            this.loadAgentConversationsInBackground(currentSnapshot, project, projectLoadToken)
            void this.loadFullProjectInBackground(project, config.projectFolder, config.workingFolder, projectLoadToken)
            telemetryService.trackEvent('open_project')

            return currentSnapshot
        } catch (error) {
            this.clearFailedProjectLoad()
            dialogService.error(error, { fallbackMessage: 'Project could not be loaded', title: 'Project load failed' })
            telemetryService.captureError(error)
            markProjectLoadErrorReported(error)
            throw error
        }
    }
import {
    Button,
    Dialog,
    DialogActions,
    DialogContent,
    DialogTitle,
    Divider,
    FormControl,
    InputLabel,
    MenuItem,
    Select,
    Stack,
    TextField,
    Typography,
} from '@mui/material'
import type { SelectChangeEvent } from '@mui/material'
import type { ChangeEvent } from 'react'
import { useState } from 'react'
import { DEFAULT_PROJECT_FOLDER, type BranchReference, type ProjectReference, type RepositoryReference, type TopLevelFolderReference } from '../../../data/data_types'
import { tryReadRemoteControlConnection } from '../../../data/remote_control_connection'
import type { ProjectOpenResolution } from '../../../services/project/project_session_service'
import { ProjectFolderSetupForm } from './project_folder_setup_form'
import { WorkingFolderChooserDialog } from './working_folder_chooser_dialog'

type ProjectSource = 'github' | 'remote'

interface GithubBranchesResult {
    branches: BranchReference[]
    repository: RepositoryReference
}

interface ProjectOpenDialogProps {
    branches: BranchReference[]
    initialRemoteProject?: ProjectReference | null
    initialSource?: ProjectSource | null
    isDesktopMode: boolean
    isGithubAuthenticated: boolean
    isLoading: boolean
    projectOpenResolution: ProjectOpenResolution | null
    open: boolean
    pendingGithubConflictProject: ProjectReference | null
    repositories: RepositoryReference[]
    onBranchChange: (branch: string) => void
    onClose: () => void
    onCreateProjectFolders: (projectFolder: string) => void
    onCreateRemoteProject: (rootPath: string, branch: string) => ProjectReference
    onCreateWorkingFolder: () => void
    onDiscardGithubPendingCommits: () => void
    onLoadManualBranches: (owner: string, repository: string) => Promise<GithubBranchesResult | null>
    onLoadRemoteBranches: (endpoint: string, token: string, rootPath: string, branch: string) => Promise<BranchReference[]>
    onOpenGithub: (owner: string, repository: string, branch: string) => Promise<void>
    onOpenRemote: (endpoint: string, token: string, project: ProjectReference) => Promise<void>
    onRepositoryChange: (repository: RepositoryReference) => Promise<BranchReference[]>
    onSourceChange: () => void
    onUseWorkingFolder: (folder: TopLevelFolderReference) => void
}

function branchExists(branches: BranchReference[], branchName: string) {
    return branches.some(({ name }) => name === branchName)
}

function branchValue(branches: BranchReference[], preferredBranch: string) {
    if (branchExists(branches, preferredBranch)) return preferredBranch

    return branches[0]?.name ?? ''
}

function selectValueExists(options: string[], value: string) {
    return options.some((option) => option === value)
}

function repositoryMatchesFilter(repository: RepositoryReference, filter: string) {
    const normalizedFilter = filter.trim().toLowerCase()
    if (normalizedFilter.length === 0) return true

    return repository.id.toLowerCase().includes(normalizedFilter)
}

/** Project open dialog for GitHub, local and remote project sources. */
export function ProjectOpenDialog(props: ProjectOpenDialogProps) {
    const {
        branches,
        initialRemoteProject,
        initialSource,
        isDesktopMode,
        isGithubAuthenticated,
        isLoading,
        onBranchChange,
        onClose,
        onCreateProjectFolders,
        onCreateRemoteProject,
        onCreateWorkingFolder,
        onDiscardGithubPendingCommits,
        onLoadManualBranches,
        onLoadRemoteBranches,
        onOpenGithub,
        onOpenRemote,
        onRepositoryChange,
        onSourceChange,
        onUseWorkingFolder,
        open,
        pendingGithubConflictProject,
        projectOpenResolution,
        repositories,
    } = props
    const [githubOwner, setGithubOwner] = useState('')
    const [githubRepository, setGithubRepository] = useState('')
    const [projectFolder, setProjectFolder] = useState(DEFAULT_PROJECT_FOLDER)
    const [repositoryFilter, setRepositoryFilter] = useState('')
    const [remoteEndpoint, setRemoteEndpoint] = useState('')
    const [remoteRootPath, setRemoteRootPath] = useState('')
    const [remoteToken, setRemoteToken] = useState('')
    const [selectedBranch, setSelectedBranch] = useState('')
    const [selectedRepositoryId, setSelectedRepositoryId] = useState('')
    const [source, setSource] = useState<ProjectSource>('github')
    const [wasOpen, setWasOpen] = useState(false)

    if (open !== wasOpen) {
        setWasOpen(open)
        if (open) {
            if (initialSource) setSource(initialSource)
            const stored = tryReadRemoteControlConnection()
            if (stored) {
                if (remoteEndpoint.length === 0) setRemoteEndpoint(stored.endpoint)
                if (remoteToken.length === 0) setRemoteToken(stored.token)
            }
            if (initialRemoteProject) {
                if (remoteRootPath.length === 0 && initialRemoteProject.rootPath) setRemoteRootPath(initialRemoteProject.rootPath)
                if (selectedBranch.length === 0 && initialRemoteProject.branch) setSelectedBranch(initialRemoteProject.branch)
            }
        }
    }

    const projectFolderSetup = projectOpenResolution?.kind === 'project-folder-setup' ? projectOpenResolution : null
    const missingWorkingFolder = projectOpenResolution?.kind === 'missing-working-folder' ? projectOpenResolution : null
    const filteredRepositories = repositories.filter((repository) => repositoryMatchesFilter(repository, repositoryFilter))
    const filteredRepositoryIds = filteredRepositories.map(({ id }) => id)
    const isRemoteComplete = remoteEndpoint.length > 0 && remoteToken.length > 0 && remoteRootPath.length > 0
    const branchNames = branches.map(({ name }) => name)
    const branchSelectValue = selectValueExists(branchNames, selectedBranch) ? selectedBranch : ''
    const repositorySelectValue = selectValueExists(filteredRepositoryIds, selectedRepositoryId) ? selectedRepositoryId : ''

    const handleSourceChange = (event: SelectChangeEvent) => {
        setSource(event.target.value as ProjectSource)
        setSelectedBranch('')
        setSelectedRepositoryId('')
        onSourceChange()
    }

    const handleRepositoryFilterChange = (event: ChangeEvent<HTMLInputElement>) => {
        setRepositoryFilter(event.target.value)
    }

    const handleGithubOwnerChange = (event: ChangeEvent<HTMLInputElement>) => {
        setGithubOwner(event.target.value)
    }

    const handleGithubRepositoryChange = (event: ChangeEvent<HTMLInputElement>) => {
        setGithubRepository(event.target.value)
    }

    const handleRemoteEndpointChange = (event: ChangeEvent<HTMLInputElement>) => {
        setRemoteEndpoint(event.target.value)
    }

    const handleRemoteRootPathChange = (event: ChangeEvent<HTMLInputElement>) => {
        setRemoteRootPath(event.target.value)
    }

    const handleRemoteTokenChange = (event: ChangeEvent<HTMLInputElement>) => {
        setRemoteToken(event.target.value)
    }

    const handleBranchChange = (event: SelectChangeEvent) => {
        setSelectedBranch(event.target.value)
        onBranchChange(event.target.value)
    }

    const handleBranchTextChange = (event: ChangeEvent<HTMLInputElement>) => {
        setSelectedBranch(event.target.value)
        onBranchChange(event.target.value)
    }

    const handleRepositoryChange = async (event: SelectChangeEvent) => {
        const repositoryId = event.target.value
        const repository = repositories.find((candidate) => candidate.id === repositoryId)
        setSelectedRepositoryId(repositoryId)
        if (!repository) return

        setGithubOwner(repository.owner)
        setGithubRepository(repository.repository)
        const nextBranches = await onRepositoryChange(repository)
        const branch = branchValue(nextBranches, repository.branch)
        setSelectedBranch(branch)
        onBranchChange(branch)
    }

    const handleLoadManualBranchesClick = async () => {
        const result = await onLoadManualBranches(githubOwner, githubRepository)
        if (!result) return

        const branch = branchValue(result.branches, result.repository.branch)
        setSelectedRepositoryId(result.repository.id)
        setSelectedBranch(branch)
        onBranchChange(branch)
    }

    const handleLoadRemoteBranchesClick = async () => {
        const nextBranches = await onLoadRemoteBranches(remoteEndpoint, remoteToken, remoteRootPath, selectedBranch || 'main')
        const branch = branchValue(nextBranches, selectedBranch || 'main')
        setSelectedBranch(branch)
        onBranchChange(branch)
    }

    const handleOpenGithubClick = () => {
        void onOpenGithub(githubOwner, githubRepository, selectedBranch)
    }

    const handleOpenRemoteClick = () => {
        if (remoteEndpoint.length === 0 || remoteToken.length === 0 || remoteRootPath.length === 0) return

        const project = onCreateRemoteProject(remoteRootPath, selectedBranch || 'main')
        void onOpenRemote(remoteEndpoint, remoteToken, project)
    }

    const handleProjectFolderChange = (value: string) => {
        setProjectFolder(value)
    }

    const handleCreateProjectFoldersClick = () => {
        onCreateProjectFolders(projectFolder)
    }

    const handleClose = () => {
        setProjectFolder(DEFAULT_PROJECT_FOLDER)
        onClose()
    }

    return (
        <Dialog fullWidth maxWidth="sm" onClose={handleClose} open={open}>
            <DialogTitle>{projectFolderSetup ? 'Create project' : 'Open project'}</DialogTitle>
            <DialogContent>
                <Stack spacing={2} sx={{ pt: 1 }}>
                    {pendingGithubConflictProject ? (
                        <Stack direction={{ xs: 'column', sm: 'row' }} spacing={1} sx={{ alignItems: { sm: 'center' } }}>
                            <Typography color="text.secondary" sx={{ flex: 1 }} variant="body2">
                                Unpushed GitHub commits conflict with this branch.
                            </Typography>
                            <Button onClick={onDiscardGithubPendingCommits} size="small" variant="outlined">
                                Discard pending commits
                            </Button>
                        </Stack>
                    ) : null}
                    {!projectOpenResolution && !isDesktopMode ? <FormControl size="small">
                        <InputLabel id="project-source-label">Source</InputLabel>
                        <Select label="Source" labelId="project-source-label" onChange={handleSourceChange} value={source}>
                            <MenuItem value="github">GitHub</MenuItem>
                            <MenuItem value="remote">Remote</MenuItem>
                        </Select>
                    </FormControl> : null}
                    {!projectOpenResolution && !isDesktopMode && source === 'github' ? (
                        <>
                            <TextField disabled={!isGithubAuthenticated} label="Filter repositories" onChange={handleRepositoryFilterChange} size="small" value={repositoryFilter} />
                            <FormControl disabled={!isGithubAuthenticated || repositories.length === 0} size="small">
                                <InputLabel id="repository-label">Repository</InputLabel>
                                <Select label="Repository" labelId="repository-label" onChange={handleRepositoryChange} value={repositorySelectValue}>
                                    {filteredRepositories.map((repository) => (
                                        <MenuItem key={repository.id} value={repository.id}>{repository.id}</MenuItem>
                                    ))}
                                </Select>
                            </FormControl>
                            <Divider />
                            <Typography variant="subtitle2">Manual GitHub repository</Typography>
                            <Stack direction={{ xs: 'column', sm: 'row' }} spacing={2}>
                                <TextField disabled={!isGithubAuthenticated} label="Owner" onChange={handleGithubOwnerChange} size="small" value={githubOwner} />
                                <TextField disabled={!isGithubAuthenticated} label="Repository" onChange={handleGithubRepositoryChange} size="small" value={githubRepository} />
                            </Stack>
                            <Button disabled={!isGithubAuthenticated || githubOwner.length === 0 || githubRepository.length === 0 || isLoading} onClick={handleLoadManualBranchesClick} variant="outlined">
                                Load branches
                            </Button>
                        </>
                    ) : !projectOpenResolution && !isDesktopMode ? (
                        <>
                            <TextField label="Endpoint" onChange={handleRemoteEndpointChange} size="small" value={remoteEndpoint} />
                            <TextField label="Token" onChange={handleRemoteTokenChange} size="small" type="password" value={remoteToken} />
                            <TextField label="Project root path" onChange={handleRemoteRootPathChange} size="small" value={remoteRootPath} />
                            <TextField label="Branch" onChange={handleBranchTextChange} size="small" value={selectedBranch || 'main'} />
                            <Button
                                disabled={!isRemoteComplete || isLoading}
                                onClick={handleLoadRemoteBranchesClick}
                                variant="outlined"
                            >
                                Load remote branches
                            </Button>
                        </>
                    ) : null}
                    {!projectOpenResolution && !isDesktopMode && source !== 'remote' ? (
                        branches.length > 0 ? (
                            <FormControl size="small">
                                <InputLabel id="open-branch-label">Branch</InputLabel>
                                <Select label="Branch" labelId="open-branch-label" onChange={handleBranchChange} value={branchSelectValue}>
                                    {branches.map(({ name }) => <MenuItem key={name} value={name}>{name}</MenuItem>)}
                                </Select>
                            </FormControl>
                        ) : (
                            <TextField label="Branch" onChange={handleBranchTextChange} size="small" value={selectedBranch} />
                        )
                    ) : null}
                    {projectFolderSetup ? (
                        <ProjectFolderSetupForm
                            folders={projectFolderSetup.folders}
                            onProjectFolderChange={handleProjectFolderChange}
                            projectFolder={projectFolder}
                        />
                    ) : null}
                    {missingWorkingFolder ? (
                        <WorkingFolderChooserDialog
                            isLoading={isLoading}
                            onCreateWorkingFolder={onCreateWorkingFolder}
                            onUseWorkingFolder={onUseWorkingFolder}
                            resolution={missingWorkingFolder}
                        />
                    ) : null}
                </Stack>
            </DialogContent>
            <DialogActions>
                <Button onClick={handleClose}>Cancel</Button>
                {projectFolderSetup ? (
                    <Button disabled={projectFolder.trim().length === 0 || isLoading} onClick={handleCreateProjectFoldersClick} variant="contained">
                        Create
                    </Button>
                ) : !projectOpenResolution && !isDesktopMode && source === 'github' ? (
                    <Button disabled={!isGithubAuthenticated || githubOwner.length === 0 || githubRepository.length === 0 || isLoading} onClick={handleOpenGithubClick} variant="contained">
                        Open GitHub
                    </Button>
                ) : !projectOpenResolution && !isDesktopMode && source === 'remote' ? (
                    <Button
                        disabled={!isRemoteComplete || isLoading}
                        onClick={handleOpenRemoteClick}
                        variant="contained"
                    >
                        Open Remote
                    </Button>
                ) : null}
            </DialogActions>
        </Dialog>
    )
}

import {
    DEFAULT_PROJECT_CONFIG,
    MISSING_WORKING_FOLDER_ERROR,
    resolveProjectConfigPaths,
    type BranchReference,
    type CardDraft,
    type ProjectReference,
    type RepositoryReference,
    type StorageService,
    type TopLevelFolderReference,
} from '../../data/data_types'
import { deriveStatesFromCards, mergeStatesWithDefaults } from '../../data/card_ordering'
import { createStorageService, writeLastProject, type StorageType } from '../../data/project_session'
import { activateStorageService } from '../../data/project_storage_activation'
import { configureRemoteControlConnection } from '../../data/remote_control_connection'
import { configService } from '../config/config_service'
import { dataService } from '../data/data_service'
import { dialogService } from '.././dialog_service'
import { GithubPendingCommitConflictError, GithubStorageService } from '../github/github_storage_service'
import { markdownParsingService } from '../data/markdown_parsing_service'
import { register } from '.././service_injector'
import { createRandomProjectBackgroundShade } from '../../theme/project_background_shade'
import { isProjectLoadErrorReported } from './project_loading'
import { projectPersistenceService } from './project_persistence_service'
import { createDefaultActionFiles } from '../../project_template/project_template'

export interface MissingWorkingFolderResolution {
    kind: 'missing-working-folder'
    configuredWorkingFolder: string
    folders: TopLevelFolderReference[]
    project: ProjectReference
    resolvedWorkingFolder: string
    storageType: StorageType
}

export interface ProjectFolderSetupResolution {
    folders: TopLevelFolderReference[]
    kind: 'project-folder-setup'
    project: ProjectReference
    storageType: 'github' | 'local'
}

export type ProjectOpenResolution = MissingWorkingFolderResolution | ProjectFolderSetupResolution

export interface ProjectSessionState {
    errorMessage: string | null
    isCommitting: boolean
    isLoading: boolean
    isPulling: boolean
    isPushing: boolean
    pendingGithubConflictProject: ProjectReference | null
}

const EMPTY_TOP_LEVEL_FOLDERS: TopLevelFolderReference[] = []

function isMissingWorkingFolderError(error: unknown): error is { workingFolder: string } {
    if (!error || typeof error !== 'object') return false

    const storageError = error as { code?: unknown; workingFolder?: unknown }

    return storageError.code === MISSING_WORKING_FOLDER_ERROR && typeof storageError.workingFolder === 'string'
}

function createGithubStorage(accessToken: string | null) {
    const storage = new GithubStorageService()
    storage.init({ accessToken: accessToken ?? '' })

    return storage
}

async function persistWorkingFolder(storage: StorageService, project: ProjectReference, workingFolder: string) {
    const projectConfig = await storage.loadProjectConfig(project)
    configService.loadProjectConfig(projectConfig)
    let nextConfig = { ...configService.getProjectConfig(), workingFolder }
    if (projectConfig?.states === undefined) {
        const resolvedConfig = resolveProjectConfigPaths(nextConfig)
        const projectFiles = await storage.loadProjectRoot(project, resolvedConfig.workingFolder)
        const { activeCards } = markdownParsingService.splitCards(projectFiles.files, resolvedConfig.workingFolder)
        const derivedStates = deriveStatesFromCards(activeCards)
        nextConfig = { ...nextConfig, states: mergeStatesWithDefaults(derivedStates) }
    }
    configService.loadProjectConfig(nextConfig)
    await storage.saveProjectConfig(project, nextConfig)
}

function requireProjectFolder(projectFolder: string) {
    const normalizedFolder = projectFolder.trim().replace(/\\/gu, '/')
    if (normalizedFolder.length === 0) throw new Error('Project folder is required')
    if (normalizedFolder === '.' || normalizedFolder === '..' || normalizedFolder.includes('/')) {
        throw new Error('Project folder must be a root folder name')
    }

    return normalizedFolder
}

async function listTopLevelFolders(storage: StorageService, project: ProjectReference) {
    try {
        return await storage.listTopLevelFolders(project)
    } catch {
        return EMPTY_TOP_LEVEL_FOLDERS
    }
}

async function createMissingWorkingFolderResolution(
    storage: StorageService,
    storageType: StorageType,
    project: ProjectReference,
): Promise<MissingWorkingFolderResolution> {
    const config = configService.getProjectConfig()
    const resolvedConfig = resolveProjectConfigPaths(config)
    const folders = await listTopLevelFolders(storage, project)

    return {
        configuredWorkingFolder: config.workingFolder,
        folders,
        kind: 'missing-working-folder',
        project,
        resolvedWorkingFolder: resolvedConfig.workingFolder,
        storageType,
    }
}

async function loadProjectSession(storage: StorageService, storageType: StorageType, project: ProjectReference) {
    try {
        await projectPersistenceService.flushPendingChanges()
        dataService.init({ storage })
        activateStorageService(storageType, storage)
        await dataService.projectLoading.openProject(project)
        writeLastProject(storageType, project)

        return null
    } catch (error) {
        if (!isMissingWorkingFolderError(error)) throw error

        return createMissingWorkingFolderResolution(storage, storageType, project)
    }
}

export class ProjectSessionService extends EventTarget {
    private state: ProjectSessionState = {
        errorMessage: null,
        isCommitting: false,
        isLoading: false,
        isPulling: false,
        isPushing: false,
        pendingGithubConflictProject: null,
    }

    constructor() {
        super()
        register('projectSessionService', this)
    }

    getSnapshot(): ProjectSessionState {
        return this.state
    }

    setError(message: string | null) {
        this.state = { ...this.state, errorMessage: message, pendingGithubConflictProject: null }
        this.dispatchChanged()
    }

    async listRepositories(accessToken: string | null): Promise<RepositoryReference[]> {
        return this.withLoading('Repository list failed', async () => createGithubStorage(accessToken).listRepositories())
    }

    async listBranches(storageType: StorageType, project: ProjectReference, accessToken: string | null): Promise<BranchReference[]> {
        return this.withLoading('Branch list failed', async () => {
            const storage = createStorageService(storageType, accessToken)

            return storage.listBranches(project)
        })
    }

    async findGithubRepositoryBranches(owner: string, repositoryName: string, accessToken: string | null) {
        return this.withLoading('Manual repository branch list failed', async () => {
            const storage = createGithubStorage(accessToken)
            const repository = await storage.findRepository(owner, repositoryName)
            const branches = await storage.listBranches(repository)

            return { branches, repository }
        })
    }

    async openProject(
        storageType: StorageType,
        project: ProjectReference,
        accessToken: string | null,
        existingStorage?: StorageService,
    ): Promise<ProjectOpenResolution | null> {
        return this.withLoading('Project load failed', async () => {
            const storage = existingStorage ?? createStorageService(storageType, accessToken)
            if (storageType === 'github' || storageType === 'local') {
                const projectConfig = await storage.loadProjectConfig(project)
                if (projectConfig !== null) return loadProjectSession(storage, storageType, project)

                const folders = await listTopLevelFolders(storage, project)

                return { folders, kind: 'project-folder-setup', project, storageType }
            }

            return loadProjectSession(storage, storageType, project)
        })
    }

    async openWorkingFolder(resolution: MissingWorkingFolderResolution, folder: TopLevelFolderReference, accessToken: string | null) {
        await this.withLoading('Working folder selection failed', async () => {
            const storage = createStorageService(resolution.storageType, accessToken)
            await persistWorkingFolder(storage, resolution.project, folder.path)
            await projectPersistenceService.flushPendingChanges()
            dataService.init({ storage })
            activateStorageService(resolution.storageType, storage)
            await dataService.projectLoading.openProject(resolution.project)
            writeLastProject(resolution.storageType, resolution.project)
        })
    }

    async createWorkingFolder(resolution: MissingWorkingFolderResolution, accessToken: string | null) {
        await this.withLoading('Working folder creation failed', async () => {
            const storage = createStorageService(resolution.storageType, accessToken)
            const project = await storage.createProject(resolution.project, resolution.resolvedWorkingFolder)
            await persistWorkingFolder(storage, project, resolution.configuredWorkingFolder)
            await projectPersistenceService.flushPendingChanges()
            dataService.init({ storage })
            activateStorageService(resolution.storageType, storage)
            await dataService.projectLoading.openProject(project)
            writeLastProject(resolution.storageType, project)
        })
    }

    async createProjectFolders(resolution: ProjectFolderSetupResolution, projectFolder: string, accessToken: string | null) {
        await this.withLoading('Project folder creation failed', async () => {
            const storage = createStorageService(resolution.storageType, accessToken)
            const normalizedProjectFolder = requireProjectFolder(projectFolder)
            const projectConfig = {
                ...DEFAULT_PROJECT_CONFIG,
                backgroundShade: createRandomProjectBackgroundShade(),
                projectFolder: normalizedProjectFolder,
            }
            const resolvedConfig = resolveProjectConfigPaths(projectConfig)
            const project = await storage.createProject(resolution.project, resolvedConfig.workingFolder)
            await storage.commit({
                branch: project.branch,
                files: createDefaultActionFiles(resolvedConfig.actionsFolder),
                message: 'Add default MDÂ² actions',
            })
            await storage.saveProjectConfig(project, projectConfig)
            configService.loadProjectConfig(projectConfig)
            await projectPersistenceService.flushPendingChanges()
            dataService.init({ storage })
            activateStorageService(resolution.storageType, storage)
            await dataService.projectLoading.openProject(project)
            writeLastProject(resolution.storageType, project)
        })
    }

    configureRemote(endpoint: string, token: string) {
        this.setError(null)
        configureRemoteControlConnection({ endpoint, token })
    }

    async switchBranch(branch: string) {
        await this.withLoading('Branch switch failed', () => dataService.projectLoading.switchBranch(branch))
    }

    async push() {
        this.state = { ...this.state, isPushing: true }
        this.dispatchChanged()

        try {
            await this.withLoading('Push failed', async () => {
                await projectPersistenceService.flushPendingChanges()
                await dataService.projectLoading.push()
            })
        } finally {
            this.state = { ...this.state, isPushing: false }
            this.dispatchChanged()
        }
    }

    async commit() {
        this.state = { ...this.state, isCommitting: true }
        this.dispatchChanged()

        try {
            await this.withLoading('Commit failed', () => projectPersistenceService.flushPendingChanges())
        } finally {
            this.state = { ...this.state, isCommitting: false }
            this.dispatchChanged()
        }
    }

    async pull() {
        this.state = { ...this.state, isPulling: true }
        this.dispatchChanged()

        try {
            await this.withLoading('Pull failed', () => dataService.projectLoading.pull())
        } finally {
            this.state = { ...this.state, isPulling: false }
            this.dispatchChanged()
        }
    }

    discardGithubPendingCommits(project: ProjectReference, accessToken: string | null) {
        const storage = createGithubStorage(accessToken)
        storage.discardPendingCommits(project)
        this.state = { ...this.state, errorMessage: null, pendingGithubConflictProject: null }
        this.dispatchChanged()
    }

    async completeRelease(releaseName: string) {
        await this.withLoading('Release completion failed', () => dataService.releases.completeRelease(releaseName))
    }

    async createCard(draft: CardDraft) {
        await this.withLoading('Card creation failed', () => dataService.cards.createCard(draft))
    }

    private async withLoading<T>(fallbackMessage: string, operation: () => Promise<T>): Promise<T> {
        this.state = { ...this.state, errorMessage: null, isLoading: true, pendingGithubConflictProject: null }
        this.dispatchChanged()

        try {
            return await operation()
        } catch (error) {
            const message = error instanceof Error ? error.message : fallbackMessage
            this.state = {
                ...this.state,
                errorMessage: message,
                isLoading: false,
                pendingGithubConflictProject: error instanceof GithubPendingCommitConflictError ? error.project : null,
            }
            this.dispatchChanged()
            if (!isProjectLoadErrorReported(error)) dialogService.error(error, { fallbackMessage })
            throw error
        } finally {
            if (this.state.isLoading) {
                this.state = { ...this.state, isLoading: false }
                this.dispatchChanged()
            }
        }
    }

    private dispatchChanged() {
        this.dispatchEvent(new CustomEvent<ProjectSessionState>('changed', { detail: this.state }))
    }
}

